export function wingsGeometry(perched = false) {
  const data=models[perched ? 1 : 0], geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(data.position,3));
  geometry.setAttribute('normal',new THREE.Float32BufferAttribute(data.normal,3));
  geometry.setAttribute('aWing',new THREE.Float32BufferAttribute(data.wing,1));
  geometry.setIndex(data.index);
  geometry.computeBoundingBox();
  return geometry;
}
// Lower elliptical wire arcs, inspired by Wings' PolesAndWires component.
// Slots are assigned once, so two birds never share a perch.
export function perchLayout(ground, count) {
  const anchors=[], paths=[], lanes=6, samples=Math.ceil(count/lanes)+2;
  for(let lane=0;lane<lanes;lane++) {
    const z=90+Math.floor(lane/2)*36+(lane%2)*5;
    let floor=-Infinity;
    for(let j=0;j<=samples;j++) floor=Math.max(floor,ground(-74+148*j/samples,z));
    const points=[];
    for(let j=0;j<=samples;j++) {
      const angle=Math.PI*1.125+Math.PI*.75*j/samples;
      const point=[80*Math.cos(angle),floor+18+8*Math.sin(angle),z];
      points.push(point);
      if(j>0&&j<samples&&anchors.length<count) anchors.push(point);
    }
    paths.push(points);
  }
  return {anchors,paths};
}
